const extraGames=[
{id:'memory-garden',cat:'Gaming',title:'Memory Garden: find six pairs of flowers',desc:'Flip two cards and find matching flowers. No timer. Take your time.',author:'Pocket Arcade',time:'Memory game · 1 min',likes:129,plays:'2.1k',bg:'#e5eed8',gameType:'memory'},
{id:'lights-out',cat:'Gaming',title:'One last puzzle: switch off all nine lights.',desc:'Tap a tile to switch it and its neighbors. Find the shortest path.',author:'Tiny Logic',time:'Logic puzzle · 3 min',likes:207,plays:'3.4k',bg:'#202a3b',gameType:'lights'},
{id:'quick-signal',cat:'Gaming',title:'Wait for green. How fast are you?',desc:'Wait for the signal to turn green, then tap. Too early does not count. Try again and find your rhythm.',author:'Pocket Arcade',time:'Reaction challenge · 20 sec',likes:98,plays:'1.8k',bg:'#eadff0',gameType:'reaction'}];extraGames.forEach(work=>work.contentType='interactive');works.unshift(...extraGames);
const extraStageBefore=stage;stage=function(w){if(w.gameType==='memory')return `<div class="slice mini-game memory-game" data-mini="memory"><div class="mini-label">MEMORY GARDEN</div><div class="memory-grid">${Array.from({length:12},(_,i)=>`<button data-flip="${i}" aria-label="Flip card ${i+1}">✿</button>`).join('')}</div><div class="mini-footer"><span data-game-status role="status">Find 6 pairs of flowers</span><button data-game-reset>Restart</button></div></div>`;if(w.gameType==='lights')return `<div class="slice mini-game lights-game" data-mini="lights"><div class="mini-label">LIGHTS OUT · Switch off every light</div><div class="lights-grid">${Array.from({length:9},(_,i)=>`<button data-light="${i}" aria-label="Light ${i+1}"></button>`).join('')}</div><div class="mini-footer"><span data-game-status role="status">Tapping also switches neighboring lights</span><button data-game-reset>Restart</button></div></div>`;if(w.gameType==='reaction')return '<div class="slice mini-game reaction-game" data-mini="reaction"><div class="mini-label">WAIT FOR GREEN</div><button class="reaction-target" data-reaction>Tap to start</button><div class="mini-footer"><span data-game-status role="status">Tap as soon as it turns green</span><button data-game-reset>Reset</button></div></div>';return extraStageBefore(w)};
function initializeMiniGames(root){root.querySelectorAll('[data-mini]').forEach(el=>{if(el.dataset.ready)return;el.dataset.ready='1';const status=el.querySelector('[data-game-status]');let timer,phase='idle',started=0,attempts=[],deck=[],opened=[],matched=new Set(),steps=0,locked=false,lights=[];const flipLight=i=>{[i,i%3>0?i-1:-1,i%3<2?i+1:-1,i-3,i+3].filter(j=>j>=0&&j<9).forEach(j=>lights[j]=!lights[j])};function reset(){clearTimeout(timer);phase='idle';attempts=[];steps=0;locked=false;opened=[];matched=new Set();if(el.dataset.mini==='memory'){deck=['🌼','🌷','🌻','🌸','🍀','🌺','🌼','🌷','🌻','🌸','🍀','🌺'];for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}el.querySelectorAll('[data-flip]').forEach(b=>{b.textContent='✿';b.disabled=false;b.classList.remove('matched')});status.textContent='Find 6 pairs of flowers'}if(el.dataset.mini==='lights'){lights=Array(9).fill(false);[0,4,8].forEach(flipLight);paintLights();status.textContent='Tapping also switches neighboring lights'}if(el.dataset.mini==='reaction'){el.querySelector('[data-reaction]').textContent='Tap to start';el.classList.remove('signal-green');status.textContent='Tap as soon as it turns green'}}function paintLights(){el.querySelectorAll('[data-light]').forEach(b=>{b.classList.toggle('lit',lights[+b.dataset.light]);b.setAttribute('aria-pressed',String(lights[+b.dataset.light]))})}el.querySelector('[data-game-reset]').onclick=reset;el.querySelectorAll('[data-flip]').forEach(b=>b.onclick=()=>{const i=+b.dataset.flip;if(locked||matched.has(i)||opened.includes(i))return;b.textContent=deck[i];opened.push(i);if(opened.length===2){steps++;const [a,c]=opened;if(deck[a]===deck[c]){matched.add(a);matched.add(c);opened=[];[a,c].forEach(j=>{const card=el.querySelector(`[data-flip="${j}"]`);card.classList.add('matched');card.disabled=true});status.textContent=matched.size===12?`Complete in ${steps} moves`:`${matched.size/2} / 6 pairs · ${steps} moves`}else{locked=true;timer=setTimeout(()=>{opened.forEach(j=>el.querySelector(`[data-flip="${j}"]`).textContent='✿');opened=[];locked=false},750);status.textContent=`${matched.size/2} / 6 pairs · ${steps} moves`}}});el.querySelectorAll('[data-light]').forEach(b=>b.onclick=()=>{if(phase==='done')return;steps++;flipLight(+b.dataset.light);paintLights();if(lights.every(x=>!x)){phase='done';status.textContent=`Lights out! ${steps} moves`}else status.textContent=`${steps} moves · Lights remaining: ${lights.filter(Boolean).length} lights`});el.querySelector('[data-reaction]')?.addEventListener('click',()=>{const b=el.querySelector('[data-reaction]');if(phase==='waiting'){clearTimeout(timer);phase='idle';b.textContent='Too soon. Try again.';return}if(phase==='go'){const ms=Math.round(performance.now()-started);attempts.push(ms);phase='idle';el.classList.remove('signal-green');b.textContent=ms+' ms · Try again';status.textContent=`${attempts.length} attempts · Best: ${Math.min(...attempts)} ms`;return}phase='waiting';b.textContent='Wait for green…';timer=setTimeout(()=>{if(!el.isConnected)return;phase='go';started=performance.now();el.classList.add('signal-green');b.textContent='Tap now!'},1200+Math.random()*2000)});reset()})}
const miniInitBefore=initStages;initStages=function(root){miniInitBefore(root);initializeMiniGames(root)};
const gamesOpenBefore=openWork;openWork=function(id,remix=false){const w=works.find(x=>x.id===id);gamesOpenBefore(id,remix);if(w?.gameType&&!remix)document.querySelector('#dialog-mode').textContent='PLAYGROUND · '+w.time};
render();
